(function(E){ const x = E["mkt-m1"] = E["mkt-m1"] || {units:{}}; x.units["mkt-4"] = {"grammar":{"id":"c-mkt-4-g","level":"B1","course":"marketing","unit":"mkt-4","title":"Suggesting changes: suggest and recommend","titleTr":"Değişiklik önermek: suggest ve recommend","titleFa":"پیشنهاد تغییر: suggest و recommend","formsTable":{"headers":{"en":["Pattern","Example"],"tr":["Yapı","Örnek"],"fa":["الگو","مثال"]},"rows":[["suggest / recommend + -ing","I suggest keeping the writer's draft."],["suggest / recommend (that) + we / you + verb","I recommend that we cut it to 100 words."],["suggest + noun","I'd suggest two changes."],["NOT suggest to + verb / suggest you to","I suggest to keep it. (wrong)"]]},"wrong":"I suggest to keep the writer's draft.","right":"I suggest keeping the writer's draft.","blank":{"sentence":"I suggest ___ the AI tool for headline ideas only.","word":"using","distractors":["to use","use"]},"wrong2":"I recommend you to cut the text to 100 words.","right2":"I recommend that you cut the text to 100 words.","blank2":{"sentence":"I suggest that we ___ \"hand-woven\" from the text.","word":"remove","distractors":["to remove","removing"]},"expParts":{"tryFrom":"blank","rule":[{"en":"suggest / recommend + -ing.","tr":"suggest / recommend + -ing.","fa":"بعد از suggest یا recommend می‌توانی فعل را با ‎-ing بیاوری.","ex":"I suggest keeping the writer's draft."},{"en":"Or + (that) + we / you + base verb.","tr":"Ya da + (that) + we / you + yalın fiil.","fa":"راه دوم: بعد از آن‌ها that بیاور (می‌شود حذفش کرد)، بعد we یا you و فعل ساده.","ex":"I recommend that we cut it to 100 words."},{"en":"Or + a noun. I'd sounds softer.","tr":"Ya da + bir isim. I'd daha yumuşak duyulur.","fa":"راه سوم: بعدشان یک اسم بیاور. با I'd پیشنهادت نرم‌تر به نظر می‌رسد.","ex":"I'd suggest two changes."},{"en":"Never \"suggest to + verb\" or \"suggest you to\".","tr":"Asla \"suggest to + fiil\" ya da \"suggest you to\" deme.","fa":"بعد از suggest هیچ‌وقت to و فعل نیاور و suggest you to هم نگو.","ex":"not \"I suggest to cut it\" or \"I suggest you to cut it\""}],"test":{"en":"After suggest, try -ing first. Want to name a person? Add that + person + base verb.","tr":"Suggest'ten sonra önce -ing dene. Bir kişi mi söylemek istiyorsun? that + kişi + yalın fiil ekle.","fa":"بعد از suggest اول -ing را امتحان کن. می‌خواهی اسم کسی را بیاوری؟ that و شخص و فعل ساده."},"contrast":{"en":"Turkish \"kısaltmanı öneririm\" and Persian «پیشنهاد می‌کنم کوتاهش کنی» join the person and the verb, so learners write \"suggest you to cut\". English says suggest cutting, or suggest that you cut.","tr":"Türkçede \"kısaltmanı öneririm\" derken kişi ve fiil birleşir; bu yüzden \"suggest you to cut\" yazılır. İngilizcede \"suggest cutting\" ya da \"suggest that you cut\" denir.","fa":"در فارسی «پیشنهاد می‌کنم کوتاهش کنی» شخص و فعل را با هم می‌آورد؛ برای همین می‌نویسیم «suggest you to cut». انگلیسی می‌گوید suggest cutting یا suggest that you cut."}},"errorWatch":[{"find":["suggest to keep","suggest to use","suggest to cut","suggest to change","suggest to remove","suggest to add","recommend to use","recommend to keep","recommend to cut","suggest you to","recommend you to","suggest her to","suggest him to","suggest them to"],"fix":{"en":"After suggest and recommend: -ing (\"I suggest cutting it\") or that + person + verb (\"I suggest that you cut it\").","tr":"Suggest ve recommend'dan sonra: -ing (\"I suggest cutting it\") ya da that + kişi + fiil (\"I suggest that you cut it\").","fa":"بعد از suggest و recommend: -ing («I suggest cutting it») یا that با شخص و فعل («I suggest that you cut it»)."}}]},"b2":{"id":"c-mkt-4-b2","level":"B2","track":"B2","course":"marketing","unit":"mkt-4","title":"Soft preferences: I'd rather you..., I'd prefer it if...","titleTr":"Yumuşak tercihler: I'd rather you..., I'd prefer it if...","titleFa":"ترجیح نرم: I'd rather you...، I'd prefer it if...","formsTable":{"headers":{"en":["Form","For","Example"],"tr":["Yapı","Kimin için","Örnek"],"fa":["ساختار","برای","مثال"]},"rows":[["I'd rather + verb","your own choice","I'd rather keep the writer's draft."],["I'd rather + you + past","someone else","I'd rather you didn't use \"hand-woven\"."],["I'd prefer it if + you + past","someone else, very polite","I'd prefer it if you sent it by Thursday."]]},"wrong":"I'd rather you don't use \"hand-woven\".","right":"I'd rather you didn't use \"hand-woven\".","blank":{"sentence":"I'd rather you ___ the word \"artisans\".","word":"didn't use","distractors":["don't use","not use"]},"wrong2":"I'd prefer it if you will send it by Thursday.","right2":"I'd prefer it if you sent it by Thursday.","blank2":{"sentence":"I'd prefer it if we ___ the call before lunch.","word":"had","distractors":["have","will have"]},"useIn":{"en":"B2: in your feedback email, ask for one change with I'd rather you... or I'd prefer it if you...","tr":"B2: geri bildirim e-postanda bir değişikliği I'd rather you... ya da I'd prefer it if you... ile iste.","fa":"B2: در ایمیل بازخوردت یک تغییر را با I'd rather you... یا I'd prefer it if you... درخواست کن."},"exitItem":{"from":"mkt-4","kind":"blank","prompt":"I'd rather you ___ the price in the first line.","options":["didn't mention","don't mention","not mentioning"],"correct":0},"expParts":{"tryFrom":"blank","rule":[{"en":"Your own choice: I'd rather + base verb.","tr":"Kendi tercihin: I'd rather + yalın fiil.","fa":"برای انتخاب خودت، I'd rather و فعل ساده می‌آید.","ex":"I'd rather keep the writer's draft."},{"en":"Someone else: I'd rather + you + past simple.","tr":"Başkası: I'd rather + you + geçmiş zaman.","fa":"برای کس دیگر، I'd rather you و گذشته‌ی ساده می‌آید.","ex":"I'd rather you didn't use \"hand-woven\"."},{"en":"Extra polite: I'd prefer it if + you + past simple.","tr":"Çok kibar: I'd prefer it if + you + geçmiş zaman.","fa":"خیلی مؤدبانه: I'd prefer it if you و گذشته‌ی ساده.","ex":"I'd prefer it if you sent it by Thursday."}],"test":{"en":"Is it someone else's action? Put the verb in the past: you didn't, you sent, we had.","tr":"Eylem başkasının mı? Fiili geçmişe koy: you didn't, you sent, we had.","fa":"کار را کس دیگری انجام می‌دهد؟ فعل را گذشته کن: you didn't، you sent، we had."},"contrast":{"en":"Persian uses the subjunctive («ترجیح می‌دهم استفاده نکنی») and Turkish says \"kullanmamanı tercih ederim\", with no past tense. English uses the past simple here, with present meaning.","tr":"Türkçede \"kullanmamanı tercih ederim\" deriz; geçmiş zaman yoktur. İngilizce burada şimdiki anlamla geçmiş zaman kullanır.","fa":"در فارسی با التزامی می‌گوییم «ترجیح می‌دهم استفاده نکنی» و زمان گذشته‌ای در کار نیست. انگلیسی اینجا گذشته‌ی ساده را با معنای حال به کار می‌برد."}},"errorWatch":[{"find":["rather you don't","rather you do not","rather you will","prefer it if you will","prefer it if we will","prefer it if you don't"],"fix":{"en":"After I'd rather you and I'd prefer it if you, use the past simple: \"I'd rather you didn't...\", \"I'd prefer it if you sent...\".","tr":"I'd rather you ve I'd prefer it if you'dan sonra geçmiş zaman kullan: \"I'd rather you didn't...\", \"I'd prefer it if you sent...\".","fa":"بعد از I'd rather you و I'd prefer it if you گذشته‌ی ساده بیاور: «I'd rather you didn't...»، «I'd prefer it if you sent...»."}}]},"vocab":{"id":"c-mkt-4-v","level":"B1","category":"vocab","course":"marketing","unit":"mkt-4","goals":["career"],"title":{"en":"Drafts and Feedback","tr":"Taslaklar ve Geri Bildirim","fa":"پیش‌نویس و بازخورد"},"cards":[{"word":"draft","sentence":"The writer's first draft arrived a day early.","meaning":{"en":"An early version of a text, not yet final.","tr":"taslak","fa":"پیش‌نویس"}},{"word":"revision","sentence":"We need one more revision before the manager signs it off.","meaning":{"en":"A changed and improved version of a text.","tr":"revizyon, düzeltilmiş hâl","fa":"نسخه‌ی اصلاح‌شده"}},{"word":"round of feedback","sentence":"The contract includes two rounds of feedback.","gap":"rounds of feedback","accept":["rounds of feedback","round of feedback"],"meaning":{"en":"One time when the client sends comments on a draft.","tr":"geri bildirim turu","fa":"دور بازخورد"}},{"word":"on-brand","sentence":"\"Warm and simple\" is on-brand; \"luxurious\" is not.","meaning":{"en":"Right for the way a brand looks and sounds.","tr":"markanın diline uygun","fa":"هماهنگ با برند"}},{"word":"cliché","sentence":"\"Indulge in softness\" is a cliché.","meaning":{"en":"A phrase used so often that it means nothing.","tr":"klişe","fa":"کلیشه"}},{"word":"fact-check","sentence":"Always fact-check what the AI tool writes about the factory.","meaning":{"en":"To check that every fact in a text is true.","tr":"doğruluğunu kontrol etmek","fa":"راستی‌آزمایی کردن"}},{"word":"tighten","sentence":"Can you tighten the text to 100 words?","meaning":{"en":"To make a text shorter and stronger.","tr":"metni sıkılaştırmak, toparlamak","fa":"جمع‌وجور کردن متن"}},{"word":"proofread","sentence":"The editor will proofread the final version.","meaning":{"en":"To read a text carefully to find small mistakes.","tr":"son okumasını yapmak","fa":"نمونه‌خوانی کردن"}},{"word":"accurate","sentence":"Every fact in the copy must be accurate.","meaning":{"en":"Exactly correct.","tr":"doğru, kesin","fa":"دقیق؛ درست"}},{"word":"assume","sentence":"The writer assumed the towels were hand-woven.","gap":"assumed","accept":["assumed","assume"],"meaning":{"en":"To think something is true without checking.","tr":"varsaymak","fa":"فرض کردن (بدون بررسی)"}}]},"judge":{"id":"c-mkt-4-j","course":"marketing","unit":"mkt-4","type":"judge","title":{"en":"Feedback that helps","tr":"İşe yarayan geri bildirim","fa":"بازخوردی که کمک می‌کند"},"prompt":"Four comments on a draft product description.","parts":["Specific","Gives a reason","Kind"],"instruction":{"en":"Tap what each comment does well. The comment to send has all three.","tr":"Her yorumun iyi yaptığı şeylere dokun. Gönderilecek yorumda üçü de vardır.","fa":"روی کارهایی که هر نظر درست انجام داده بزن. نظری که فرستاده می‌شود هر سه را دارد."},"items":[{"by":"AI tool","answer":"Consider enhancing the overall impact and flow.","present":["Kind"],"fix":{"en":"Polite, but nobody can act on it. Point to the line and the fix: \"The third sentence repeats the second; I suggest cutting it.\"","tr":"Kibar ama kimse bununla bir şey yapamaz. Satırı ve çözümü göster: \"The third sentence repeats the second; I suggest cutting it.\"","fa":"مؤدبانه است، ولی کسی با آن کاری نمی‌تواند بکند. خط و راه‌حل را نشان بده: «The third sentence repeats the second; I suggest cutting it.»"}},{"by":"Manager","answer":"Too long.","present":[],"fix":{"en":"True, but blunt and vague. Give the number and the reason: \"It's 140 words; the page has room for 100.\"","tr":"Doğru ama kaba ve belirsiz. Rakamı ve nedeni söyle: \"It's 140 words; the page has room for 100.\"","fa":"درست است، ولی تند و مبهم. عدد و دلیل را بگو: «It's 140 words; the page has room for 100.»"}},{"by":"Good model","answer":"Lovely opening. Please take out \"hand-woven\": our towels are woven on machines, and we only say what we can prove.","present":["Specific","Gives a reason","Kind"],"fix":null},{"by":"AI tool","answer":"Great job! Everything looks perfect!","present":["Kind"],"fix":{"en":"Kind, but not true, and it hides the real problems. Praise one specific thing instead.","tr":"Nazik ama doğru değil ve gerçek sorunları gizliyor. Bunun yerine belirli bir şeyi öv.","fa":"مهربانانه است، ولی درست نیست و مشکل‌های واقعی را پنهان می‌کند. به‌جایش از یک چیز مشخص تعریف کن."}}]},"writing":{"id":"c-mkt-4-w","title":{"en":"Edit an AI draft","tr":"Bir yapay zekâ taslağını düzenle","fa":"پیش‌نویس هوش مصنوعی را ویرایش کن"},"course":"marketing","unit":"mkt-4","type":"writing","difficulty":"medium","modelBy":"FEschool","portfolio":"mkt-final-4","prompt":{"en":"Edit a real AI draft from your own work, or this one for a handmade mug: \"Indulge in our world-famous artisan mug, loved by millions.\" Facts: thrown by hand in a small studio; 300 ml; dishwasher safe; no sales figures. Write (70-90 words) your better version, then feedback for the writer: what to keep, two changes with a reason for each. Use suggest or recommend.","tr":"Kendi işinden gerçek bir yapay zekâ taslağını ya da el yapımı bir kupa için şunu düzenle: \"Indulge in our world-famous artisan mug, loved by millions.\" Bilgiler: küçük bir atölyede elde yapılıyor; 300 ml; bulaşık makinesinde yıkanabilir; satış rakamı yok. Daha iyi hâlini, sonra yazara geri bildirimi yaz (70-90 kelime): neyin kalacağı, nedeniyle iki değişiklik. Suggest ya da recommend kullan.","fa":"یک پیش‌نویس واقعی هوش مصنوعی از کار خودت، یا این را برای یک لیوان دست‌ساز ویرایش کن: «Indulge in our world-famous artisan mug, loved by millions.» واقعیت‌ها: در یک کارگاه کوچک با دست ساخته می‌شود؛ ۳۰۰ میلی‌لیتر؛ قابل شست‌وشو در ماشین ظرف‌شویی؛ آمار فروش در دست نیست. نسخه‌ی بهترت را بنویس و بعد برای نویسنده بازخورد بنویس (۷۰ تا ۹۰ کلمه): چه چیزی بماند و دو تغییر، هر کدام با دلیل. از suggest یا recommend استفاده کن."},"model":"New version: Made by hand in our small studio. It holds 300 ml, and it is safe in the dishwasher.\n\nFeedback: Thanks for the quick draft. The word \"mug\" up front is clear, so let's keep it simple. I suggest two changes. First, please remove \"world-famous\" and \"loved by millions\", because they are clichés and we have no figures to prove them. Second, I recommend adding the size and the dishwasher fact, because buyers ask about them before a purchase.","frame":"New version: ___.\n\nFeedback: Thanks for ___. ___, so let's keep ___. I suggest two changes. First, please ___, because ___. Second, I recommend ___, because ___.","words":[{"word":"suggest"},{"word":"recommend"},{"word":"because"}],"minWords":60,"minSentences":5,"rubric":["Task done: a better version, what to keep, two changes with reasons","Organised: new version first, then praise, then the changes","Language: suggest and recommend with -ing or that","Tone: specific and kind; every fact can be checked"],"rubricI18n":{"tr":["Görev: daha iyi bir hâl, neyin kalacağı, nedenleriyle iki değişiklik","Düzen: önce yeni hâl, sonra övgü, sonra değişiklikler","Dil: -ing ya da that ile suggest ve recommend","Üslup: somut ve nazik; her bilgi kontrol edilebilir"],"fa":["کامل بودن کار: نسخه‌ی بهتر، چیزی که می‌ماند، دو تغییر با دلیل","نظم: اول نسخه‌ی تازه، بعد تعریف، بعد تغییرها","زبان: suggest و recommend با ‎-ing یا that","لحن: مشخص و محترمانه؛ هر واقعیت قابل‌بررسی است"]}},"speaking":{"id":"mkt-4","course":"marketing","unit":"mkt-4","topic":{"en":"Giving feedback on a call","tr":"Görüşmede geri bildirim vermek","fa":"بازخورد دادن در تماس"},"warmup":{"en":"Remember useful feedback you once got. What made it useful?","tr":"Bir zamanlar aldığın işe yarar bir geri bildirimi hatırla. Onu işe yarar yapan neydi?","fa":"یک بازخورد مفید را که گرفته‌ای به یاد بیاور. چه چیزی مفیدش کرد؟"},"questions":[{"en":"A freelance writer sent a draft a day early. Thank them and praise one exact thing.","tr":"Serbest çalışan bir yazar taslağı bir gün erken gönderdi. Teşekkür et ve belirli bir şeyi öv.","fa":"یک نویسنده‌ی فریلنس پیش‌نویس را یک روز زودتر فرستاده. تشکر کن و از یک چیز مشخص تعریف کن."},{"en":"Ask for two changes, each with a reason.","tr":"Her birinin nedenini söyleyerek iki değişiklik iste.","fa":"دو تغییر بخواه، هر کدام با دلیل."},{"en":"The writer says: \"But the client loved it!\" Answer politely, and agree a date.","tr":"Yazar diyor ki: \"But the client loved it!\" Kibarca cevap ver ve bir tarihte anlaş.","fa":"نویسنده می‌گوید: «But the client loved it!» مؤدبانه جواب بده و روی یک تاریخ توافق کن."}],"followups":[{"en":"Now give the same kind of feedback on a real text from your own work.","tr":"Şimdi aynı tür geri bildirimi kendi işinden gerçek bir metin için ver.","fa":"حالا همین نوع بازخورد را روی یک متن واقعی از کار خودت بده."}],"expressions":[{"phrase":"The part I really like is...","meaning":{"en":"Starts with exact praise.","tr":"Belirli bir övgüyle başlar.","fa":"با تعریف مشخص شروع می‌کند."}},{"phrase":"I'd suggest changing...","meaning":{"en":"Asks for a change without sounding bossy.","tr":"Emir vermeden değişiklik ister.","fa":"بدون دستور دادن تغییر می‌خواهد."}},{"phrase":"Would Thursday work?","meaning":{"en":"Agrees the next date.","tr":"Sonraki tarihte anlaşır.","fa":"روی تاریخ بعدی توافق می‌کند."}}],"model":"Thanks for the early draft. The part I really like is the opening, because it sounds like our customers. I'd suggest two changes. First, it's 140 words and the word count is 100, so could you tighten it by cutting the colours? Second, please take out hand-woven: our towels are made on machines, and every fact must be accurate. The deadline is Friday, so would Thursday work for the revision?","selfCheck":[{"en":"I praised one exact thing.","tr":"Belirli bir şeyi övdüm.","fa":"از یک چیز مشخص تعریف کردم."},{"en":"I gave a reason for each change.","tr":"Her değişikliğin nedenini söyledim.","fa":"برای هر تغییر دلیل گفتم."},{"en":"I used suggest and recommend correctly.","tr":"suggest ve recommend'ı doğru kullandım.","fa":"suggest و recommend را درست به کار بردم."},{"en":"Round 3 fitted in the time.","tr":"3. tur süreye sığdı.","fa":"دور سوم را در زمان تعیین‌شده تمام کردم."}]},"exit":{"id":"c-mkt-4-x","course":"marketing","unit":"mkt-4","type":"exit","items":[{"from":"mkt-4","kind":"blank","prompt":"I recommend ___ the headline shorter.","options":["to make","making","make"],"correct":1,"point":2},{"from":"mkt-4","kind":"mcq","prompt":"In which order should you edit a draft?","options":["Voice, clear, reader, true","True, reader, clear, voice","Clear, true, voice, reader"],"correct":1,"point":1},{"from":"mkt-4","kind":"mcq","prompt":"Which feedback comment is specific and gives a reason?","options":["Nice work, but needs more energy.","It's 140 words; please cut it to 100 so it fits the page.","Please rewrite it."],"correct":1,"point":1},{"from":"mkt-3","kind":"blank","prompt":"The photographer ___ bring lights; we have our own.","options":["mustn't","doesn't have to","must"],"correct":1},{"from":"mkt-2","kind":"blank","prompt":"Some ___ our readers open every email.","options":["of","from","in"],"correct":0},{"from":"mkt-1","kind":"mcq","prompt":"Which sentence describes a past habit that has stopped?","options":["We print catalogues.","We used to print paper catalogues.","We are printing catalogues."],"correct":1}]},"explain":{"id":"c-mkt-4-e","course":"marketing","unit":"mkt-4","type":"explain","level":"B1","title":{"en":"Editing a draft, human or AI","tr":"Taslak düzenlemek: insan ya da yapay zekâ","fa":"ویرایش پیش‌نویس: کار آدم یا هوش مصنوعی"},"objective":{"en":"After this lesson, you can edit a draft, from a person or an AI tool, and give clear, kind feedback.","tr":"Bu dersin sonunda bir insanın ya da yapay zekâ aracının yazdığı taslağı düzenleyebilecek, net ve nazik geri bildirim verebileceksin.","fa":"بعد از این درس می‌توانی پیش‌نویسی را که یک آدم یا یک ابزار هوش مصنوعی نوشته ویرایش کنی و بازخوردی روشن و محترمانه بدهی."},"hook":{"en":"An AI tool or a colleague can give you a draft in minutes, but the draft may be false or empty. Your job is to edit it in a fixed order: true, reader, clear, voice.","tr":"Bir yapay zekâ aracı ya da iş arkadaşın dakikalar içinde taslak verebilir, ama taslak yanlış ya da boş olabilir. Senin işin onu belli bir sırayla düzenlemektir: doğru, okur, açık, ses.","fa":"ابزار هوش مصنوعی یا همکارت می‌تواند در چند دقیقه پیش‌نویس به تو بدهد، ولی آن پیش‌نویس ممکن است غلط یا توخالی باشد. کار تو این است که آن را با ترتیبی ثابت ویرایش کنی: درستی، مخاطب، روشنی، صدا."},"stats":[{"label":{"en":"Key points","tr":"Ana nokta","fa":"نکته‌ی اصلی"},"value":"3"},{"label":{"en":"Key phrases","tr":"Anahtar ifade","fa":"عبارت کلیدی"},"value":"4"},{"label":{"en":"Practice tasks","tr":"Alıştırma","fa":"تمرین"},"value":"3"}],"points":[{"eyebrow":{"en":"The craft","tr":"Beceri","fa":"مهارت"},"head":{"en":"Edit in four passes","tr":"Dört turda düzenle","fa":"در چهار دور ویرایش کن"},"steps":[{"en":"True first: check facts and quotes against a source. Why improve a sentence you must delete?","tr":"Önce doğruluk: bilgileri ve alıntıları bir kaynakla karşılaştır. Sonunda sileceğin bir cümleyle neden uğraşasın?","fa":"اول درستی: واقعیت‌ها و نقل‌قول‌ها را با منبع مقایسه کن. چرا روی جمله‌ای وقت بگذاری که باید حذفش کنی؟","ex":"Made by artisans for centuries? We opened in 2011. Cut it."},{"en":"Reader: is this the reader's problem, in the reader's words? If not, people stop reading.","tr":"Okur: Bu okurun sorunu mu, onun sözleriyle mi? Değilse insanlar okumayı bırakır.","fa":"مخاطب: این مشکل خود مخاطب است و با کلمه‌های خود او؟ اگر نه، آدم‌ها خواندن را رها می‌کنند.","ex":"Tired of chasing clients for money?"},{"en":"Clear: one idea per sentence. Cut empty words, because they waste the reader's time.","tr":"Açık: cümle başına tek fikir. Boş kelimeleri çıkar, çünkü okurun vaktini harcarlar.","fa":"روشنی: هر جمله یک فکر. کلمه‌های توخالی را حذف کن، چون وقت مخاطب را می‌گیرند.","ex":"Elevate your everyday: cut. 140 words: cut to 100."},{"en":"Voice last: read it aloud against your voice sheet. Wording is easier once the content is right.","tr":"Ses en son: marka sesi sayfana bakarak yüksek sesle oku. İçerik doğru olunca kelimeleri düzeltmek daha kolaydır.","fa":"صدا در آخر: متن را کنار برگه‌ی صدای برند بلند بخوان. وقتی محتوا درست باشد، اصلاح کلمه‌ها آسان‌تر است.","ex":"Plain, not cute: Send it. Get paid. Not: Yay, invoices!"}]},{"eyebrow":{"en":"The language it needs","tr":"Bunun için gereken dil","fa":"زبانی که لازم دارد"},"head":{"en":"Suggesting changes: suggest and recommend","tr":"Değişiklik önermek: suggest ve recommend","fa":"پیشنهاد تغییر: suggest و recommend"},"steps":[{"en":"suggest / recommend + -ing.","tr":"suggest / recommend + -ing.","fa":"بعد از suggest یا recommend می‌توانی فعل را با ‎-ing بیاوری.","ex":"I suggest keeping the writer's draft."},{"en":"Or + (that) + we / you + base verb.","tr":"Ya da + (that) + we / you + yalın fiil.","fa":"راه دوم: بعد از آن‌ها that بیاور (می‌شود حذفش کرد)، بعد we یا you و فعل ساده.","ex":"I recommend that we cut it to 100 words."},{"en":"Or + a noun. I'd sounds softer.","tr":"Ya da + bir isim. I'd daha yumuşak duyulur.","fa":"راه سوم: بعدشان یک اسم بیاور. با I'd پیشنهادت نرم‌تر به نظر می‌رسد.","ex":"I'd suggest two changes."},{"en":"Never \"suggest to + verb\" or \"suggest you to\".","tr":"Asla \"suggest to + fiil\" ya da \"suggest you to\" deme.","fa":"بعد از suggest هیچ‌وقت to و فعل نیاور و suggest you to هم نگو.","ex":"not \"I suggest to cut it\" or \"I suggest you to cut it\""}],"table":{"headers":{"en":["Pattern","Example"],"tr":["Yapı","Örnek"],"fa":["الگو","مثال"]},"rows":[["suggest / recommend + -ing","I suggest keeping the writer's draft."],["suggest / recommend (that) + we / you + verb","I recommend that we cut it to 100 words."],["suggest + noun","I'd suggest two changes."],["NOT suggest to + verb / suggest you to","I suggest to keep it. (wrong)"]]},"tip":{"en":"Turkish \"kısaltmanı öneririm\" and Persian «پیشنهاد می‌کنم کوتاهش کنی» join the person and the verb, so learners write \"suggest you to cut\". English says suggest cutting, or suggest that you cut.","tr":"Türkçede \"kısaltmanı öneririm\" derken kişi ve fiil birleşir; bu yüzden \"suggest you to cut\" yazılır. İngilizcede \"suggest cutting\" ya da \"suggest that you cut\" denir.","fa":"در فارسی «پیشنهاد می‌کنم کوتاهش کنی» شخص و فعل را با هم می‌آورد؛ برای همین می‌نویسیم «suggest you to cut». انگلیسی می‌گوید suggest cutting یا suggest that you cut."},"wrong":"I suggest you to cut the first line.","right":"I suggest cutting the first line."},{"eyebrow":{"en":"At work","tr":"İş yerinde","fa":"در محیط کار"},"head":{"en":"Feedback on a draft","tr":"Taslağa geri bildirim","fa":"بازخورد روی پیش‌نویس"},"body":{"en":"Say what is good, then the change and the reason. On UK and US teams, \"I suggest\" or \"I recommend\" sounds professional. Use AI for spelling and headline ideas, not product facts: it can invent them.","tr":"Neyin iyi olduğunu söyle, değişikliği tam olarak belirt, nedenini açıkla. İngiltere ve ABD'deki ekiplerde \"I suggest\" ya da \"I recommend\" profesyonel görünür. Yapay zekâyı yazım ve başlık fikirleri için kullan, ürün bilgileri için değil, çünkü bilgi uydurabilir.","fa":"بگو چه چیزی خوب است، تغییر را دقیق بگو و دلیلش را هم بگو. در تیم‌های بریتانیایی و آمریکایی، I suggest یا I recommend حرفه‌ای به نظر می‌رسد. از هوش مصنوعی برای املا و ایده‌ی تیتر استفاده کن، نه برای واقعیت‌های محصولت، چون ممکن است آن‌ها را از خودش بسازد."},"phrases":[{"phrase":"The part I really like is...","meaning":{"en":"Starts with exact praise.","tr":"Belirli bir övgüyle başlar.","fa":"با تعریف مشخص شروع می‌کند."}},{"phrase":"I'd suggest changing...","meaning":{"en":"Asks for a change without sounding bossy.","tr":"Emir vermeden değişiklik ister.","fa":"بدون دستور دادن تغییر می‌خواهد."}},{"phrase":"Would Thursday work?","meaning":{"en":"Agrees the next date.","tr":"Sonraki tarihte anlaşır.","fa":"روی تاریخ بعدی توافق می‌کند."}},{"phrase":"fact-check","meaning":{"en":"To check that every fact in a text is true.","tr":"doğruluğunu kontrol etmek","fa":"راستی‌آزمایی کردن"}}]}],"example":{"eyebrow":{"en":"Worked example","tr":"Çözümlü örnek","fa":"مثال حل‌شده"},"head":{"en":"Edit one sentence","tr":"Bir cümleyi düzenle","fa":"یک جمله را ویرایش کن"},"item":"Indulge in luxurious softness, hand-woven by artisans for centuries. Facts: a thin 100 x 180 cm beach towel, about 300 grams; machine-woven in our own factory since 2011.","answer":"A 100 x 180 cm beach towel that weighs about 300 grams, so it packs small. Woven in our own factory since 2011.","walk":[{"en":"True first: the facts say machine-woven and 2011, so hand-woven and centuries go.","tr":"Önce doğruluk: bilgiler makine dokuması ve 2011 diyor, yani hand-woven ve centuries çıkıyor.","fa":"اول درستی متن را بررسی کن: واقعیت‌ها می‌گویند بافت ماشینی و سال ۲۰۱۱، پس hand-woven و centuries را حذف کن."},{"en":"Reader next: a beach-goer wants to know size, weight and use.","tr":"Sonra okur: plaja giden biri boyutu, ağırlığı ve kullanımı bilmek ister.","fa":"بعد مخاطب: کسی که به ساحل می‌رود می‌خواهد اندازه، وزن و کاربرد را بداند."},{"en":"Then clear and in voice: plain words a customer could say.","tr":"Sonra açık ve marka sesiyle: bir müşterinin de söyleyebileceği sade kelimeler.","fa":"بعد روشنی و صدای برند: کلمه‌های ساده‌ای که مشتری هم بگوید."}]},"quick":{"prompt":"The first thing to check in any draft is whether it is ___.","options":["true","in the brand voice","short"],"correct":0,"why":{"en":"True: there is no point polishing a sentence you will have to delete. Voice comes last, once the content is right.","tr":"True (doğru): sonunda sileceğin bir cümleyi parlatmanın anlamı yok. Marka sesi en sona kalır, içerik doğru olduktan sonra.","fa":"جواب true است، چون صیقل دادن جمله‌ای که آخرش باید حذفش کنی فایده‌ای ندارد. صدای برند آخر کار می‌آید، وقتی محتوا درست شد."}},"remember":{"en":"Good feedback names the line, the change and the reason, so the writer knows what to do. You can now edit any draft in four passes and give feedback that helps.","tr":"İyi geri bildirim satırı, değişikliği ve nedeni söyler; böylece yazar ne yapacağını bilir. Artık her taslağı dört turda düzenleyebilir ve işe yarayan geri bildirim verebilirsin.","fa":"بازخورد خوب خط، تغییر و دلیل را می‌گوید تا نویسنده بداند چه کند. حالا می‌توانی هر پیش‌نویسی را در چهار دور ویرایش کنی و بازخوردی بدهی که به کار بیاید."},"b2Point":{"eyebrow":{"en":"B2 track","tr":"B2 yolu","fa":"مسیر B2"},"head":{"en":"Soft preferences: I'd rather you..., I'd prefer it if...","tr":"Yumuşak tercihler: I'd rather you..., I'd prefer it if...","fa":"ترجیح نرم: I'd rather you...، I'd prefer it if..."},"steps":[{"en":"Your own choice: I'd rather + base verb.","tr":"Kendi tercihin: I'd rather + yalın fiil.","fa":"برای انتخاب خودت، I'd rather و فعل ساده می‌آید.","ex":"I'd rather keep the writer's draft."},{"en":"Someone else: I'd rather + you + past simple.","tr":"Başkası: I'd rather + you + geçmiş zaman.","fa":"برای کس دیگر، I'd rather you و گذشته‌ی ساده می‌آید.","ex":"I'd rather you didn't use \"hand-woven\"."},{"en":"Extra polite: I'd prefer it if + you + past simple.","tr":"Çok kibar: I'd prefer it if + you + geçmiş zaman.","fa":"خیلی مؤدبانه: I'd prefer it if you و گذشته‌ی ساده.","ex":"I'd prefer it if you sent it by Thursday."}],"table":{"headers":{"en":["Form","For","Example"],"tr":["Yapı","Kimin için","Örnek"],"fa":["ساختار","برای","مثال"]},"rows":[["I'd rather + verb","your own choice","I'd rather keep the writer's draft."],["I'd rather + you + past","someone else","I'd rather you didn't use \"hand-woven\"."],["I'd prefer it if + you + past","someone else, very polite","I'd prefer it if you sent it by Thursday."]]},"body":{"en":"B2: in your feedback email, ask for one change with I'd rather you... or I'd prefer it if you...","tr":"B2: geri bildirim e-postanda bir değişikliği I'd rather you... ya da I'd prefer it if you... ile iste.","fa":"B2: در ایمیل بازخوردت یک تغییر را با I'd rather you... یا I'd prefer it if you... درخواست کن."}}}}; })(globalThis.COURSE_FILES = globalThis.COURSE_FILES || {});
